    String find = in.next();
                                                        // string to find
    System.out.print("Enter string to replace: ");
    String replace = in.next();
                                                        // string to replace
    File sourcefile = new File(source);
                                                        // source file object
    try (
                                                        // try with resources
      Scanner input = new Scanner(sourcefile);
      PrintWriter output = new PrintWriter(target);
    ) {
      while (input.hasNext()) {
        String line = input.nextLine();
        String replaceline = line.replaceAll(find, replace);
        output.println(replaceline);
      }
    }
    catch (IOException ex) { System.out.println(ex); }
  }
}

